import symbolsJson from './symbols.json'

export const SYMBOL_CATEGORIES = [
  'Greek',
  'Arrows',
  'Relations',
  'Operators',
  'Misc',
] as const

export type SymbolCategory = (typeof SYMBOL_CATEGORIES)[number]

/** One entry of `symbols.json`, generated by `scripts/generate-symbols.mjs`. */
export type PaletteSymbol = {
  /** LaTeX command including the backslash, e.g. `\alpha`. */
  command: string
  character: string
  codepoint: string
  /** Unicode description from unicode-math-table.tex. */
  name: string
  category: SymbolCategory
  /** Package that defines the command; `null` for the LaTeX kernel. */
  package: string | null
}

export const SYMBOLS = symbolsJson as PaletteSymbol[]

/** Case-insensitive match on the command (backslash optional) or the Unicode name. */
export function searchSymbols(query: string): PaletteSymbol[] {
  const needle = query.trim().toLowerCase().replace(/^\\/, '')
  if (!needle) return SYMBOLS
  return SYMBOLS.filter(
    symbol =>
      symbol.command.slice(1).toLowerCase().includes(needle) ||
      symbol.name.toLowerCase().includes(needle)
  )
}

const USEPACKAGE = /\\usepackage\s*(?:\[[^\]]*\])?\s*\{([^}]*)\}/g

/** Package names loaded with `\usepackage` in a LaTeX source. */
export function usedPackages(source: string): Set<string> {
  const packages = new Set<string>()
  for (const [, list] of source.matchAll(USEPACKAGE)) {
    for (const name of list.split(',')) packages.add(name.trim())
  }
  return packages
}
